// Visible Session Volume Value Terrain with POC Rail
// Volume-at-price bins over visible session, POC + value-area expansion, breakout signals.

rows = input(24, "Profile Rows", 12, 36, 1)
vaPct = input(70, "Value Area Coverage Percent", 50, 90, 5)
sessLen = input(120, "Visible Session Length", 30, 300, 10)
showHist = input(true, "Show Value Histogram")
show3D = input(true, "Show 3D Terrain")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Visible session range ─────────────────────────────────────────
sessHigh = highest(high, sessLen)
sessLow = lowest(low, sessLen)
rng = sessHigh - sessLow
if rng <= 0 { rng := close * 0.01 }
binH = rng / rows

// ─── Volume-at-price bins rebuilt every bar from visible session ──
binVol = array()
i = 0
while i < rows {
    array.push(binVol, 0.0)
    i := i + 1
}
k = 0
while k < sessLen {
    tp = (high[k] + low[k] + close[k]) / 3
    vv = volume[k]
    bi = floor((tp - sessLow) / rng * rows)
    if bi < 0 { bi := 0 }
    if bi > rows - 1 { bi := rows - 1 }
    array.set(binVol, bi, array.get(binVol, bi) + vv)
    k := k + 1
}

// ─── Point of control ──────────────────────────────────────────────
pocBin = 0
pocVal = array.get(binVol, 0)
i = 1
while i < rows {
    v = array.get(binVol, i)
    if v > pocVal {
        pocVal := v
        pocBin := i
    }
    i := i + 1
}
totalVol = array.sum(binVol)
pocShare = 0.0
if totalVol > 0 { pocShare := pocVal / totalVol * 100 }
pocPrice = sessLow + (pocBin + 0.5) / rows * rng

// ─── Value area expansion from POC ─────────────────────────────────
vaLow = pocBin
vaHigh = pocBin
accum = pocVal
target = totalVol * vaPct / 100
guard = 0
while accum < target and guard < rows {
    leftVal = 0 - 1.0
    if vaLow > 0 { leftVal := array.get(binVol, vaLow - 1) }
    rightVal = 0 - 1.0
    if vaHigh < rows - 1 { rightVal := array.get(binVol, vaHigh + 1) }
    if rightVal >= leftVal and vaHigh < rows - 1 {
        vaHigh := vaHigh + 1
        accum := accum + rightVal
    } else {
        if vaLow > 0 {
            vaLow := vaLow - 1
            accum := accum + leftVal
        }
    }
    guard := guard + 1
}
vahPrice = sessLow + (vaHigh + 1) / rows * rng
valPrice = sessLow + vaLow / rows * rng
vaShare = 0.0
if totalVol > 0 { vaShare := accum / totalVol * 100 }
vaWidth = vahPrice - valPrice

// ─── Location and signals: leaving value ───────────────────────────
insideVA = close >= valPrice and close <= vahPrice
prevInside = close[1] >= valPrice[1] and close[1] <= vahPrice[1]
buySig = not insideVA and prevInside and close > vahPrice
sellSig = not insideVA and prevInside and close < valPrice
coneSize = 0.6 + pocShare / 100 * 1.6
if coneSize > 2.2 { coneSize := 2.2 }
coneSize = coneSize * markerSize

// ─── POC rail label on new POC bin only ────────────────────────────
var wasPocBin = -1
if pocBin != wasPocBin {
    label3d(bar_index, pocShare, "POC", "#ffd43b", 1.0, 2, "separate")
}
wasPocBin := pocBin

// ─── Signal markers: 2D main chart ─────────────────────────────────
if buySig { plotshape(bar_index, low, "Buy", "triangleup", "#22cc88") }
if sellSig { plotshape(bar_index, high, "Sell", "triangledown", "#ff4477") }

// ─── Signal markers: 3D cones in same pane ─────────────────────────
if buySig { plotshape_3d(bar_index, vahPrice, "Buy", "coneup", "#22cc88", coneSize, 2, "separate") }
if sellSig { plotshape_3d(bar_index, valPrice, "Sell", "conedown", "#ff4477", coneSize, 2, "separate") }

// ─── 2D: same information when 3D is off ───────────────────────────
plot(close, "Price", "#ffffff", 1)
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vahPrice, "Value Area High", "#22cc88", 1, "stepline")
plot(valPrice, "Value Area Low", "#ff4477", 1, "stepline")
fill("Value Area High", "Value Area Low", "rgba(34,204,136,0.12)")
plot(pocShare, "POC Share", "#ffd43b", 1, "separate")
plot(vaShare, "Value Share", "#22cc88", 1, "separate")

// ─── 3D: value terrain + plateau + POC rail ────────────────────────
plot3d(pocShare, "Value Terrain", "surface", "#b48cff", "separate", 0)
plot3d(vaShare, "Value Plateau", "ridgeline", "#22cc88", "separate", 1)

// ─── Zone tint ─────────────────────────────────────────────────────
if not insideVA { bgcolor("rgba(255,68,119,0.05)") }

// Fix 1: var lvl = highest(high, 20) froze at bar 0 -> plain assignment recomputed every bar.
// Fix 2: close[-1] reads the future bar -> use close for no-lookahead breakout.
// Fix 3: plotshape(true, low, "Buy", shape.triangleup, color.green) is Pine signature -> OakScript uses (bar_index, price, title, style, color) with quoted strings.
// Fix 4: RSI oscillator in pane="3d" renders as spiky forest over candles -> pane="separate".
lvl = highest(high, 20)
r = rsi(close, 14)
buySig = close > lvl
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if crossover(r, 30) {
    plotshape(bar_index, low, "OS", "triangleup", "#22cc88")
}
plot3d(r, "RSI", "surface", "#b48cff", "separate")
